function cm_randInt(a,b){return Math.floor(Math.random()*(b-a+1))+a;}
function cm_genDeviceInfo(){return cm_randInt(1000000,9999999)+'V-'+cm_randInt(1000,9999);}
function cm_genDevice(){
  function rA(){return String.fromCharCode(65+cm_randInt(0,25));}
  function rD(){return String.fromCharCode(48+cm_randInt(0,9));}
  return rA()+rA()+rD()+rA()+'.'+rD()+rD()+rD()+rD()+rD()+rD()+'.'+rD()+rD()+rD();
}
function cm_genPseudoid(){
  var c='abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';var s='';
  for(var i=0;i<16;i++)s+=c.charAt(cm_randInt(0,c.length-1));
  return s;
}
function cm_headers(){
  var secret='M2FmMDg1OTAzMTEwMzJlZmUwNjYwNTUwYTA1NjNhNTM=';
  var ts=Math.floor(Date.now()/1000).toString();
  var key=java.base64DecodeToByteArray(secret);
  var mac=Packages.javax.crypto.Mac.getInstance('HmacSHA256');
  mac.init(new Packages.javax.crypto.spec.SecretKeySpec(key,'HmacSHA256'));
  var sig=Packages.android.util.Base64.encodeToString(mac.doFinal(java.strToBytes(ts)),2);
  var deviceinfo=java.get('_deviceinfo');
  if(!deviceinfo){deviceinfo=cm_genDeviceInfo();java.put('_deviceinfo',deviceinfo);}
  var device=java.get('_device');
  if(!device){device=cm_genDevice();java.put('_device',device);}
  var pseudoid=java.get('_pseudoid');
  if(!pseudoid){pseudoid=cm_genPseudoid();java.put('_pseudoid',pseudoid);}
  var d=new Date();
  var y=d.getFullYear();
  var mo=('0'+(d.getMonth()+1)).slice(-2);
  var day=('0'+d.getDate()).slice(-2);
  return JSON.stringify({
    'User-Agent':'COPY/3.0.6','source':'copyApp','deviceinfo':deviceinfo,
    'dt':y+'.'+mo+'.'+day,'platform':'3','referer':'com.copymanga.app-3.0.6','version':'3.0.6',
    'device':device,'pseudoid':pseudoid,'Accept':'application/json','region':'0',
    'authorization':'Token','umstring':'b4c89ca4104ea9a97750314d791520ac',
    'x-auth-timestamp':ts,'x-auth-signature':sig
  });
}

ruleSearch.bookList:
@js:(function(){
var d=JSON.parse(result).results.list;var out=[];
for(var i=0;i<d.length;i++){
  var c=d[i];
  var comic=c.comic||c;
  var au=(comic.author&&comic.author[0])?comic.author[0].name:'';
  out.push({name:comic.name,author:au,coverUrl:comic.cover,bookUrl:'https://api.copy2000.online/api/v3/comic2/'+comic.path_word+'?in_mainland=true&platform=3',intro:comic.datetime_updated||''});
}
return out;})()

ruleToc.chapterList:
@js:(function(){
var d=JSON.parse(result).results;
var m=book.bookUrl.match(/comic2\/([^\/?]+)/);
if(!m)return [];
var cid=m[1];
var groups=d.groups||{};
var out=[];
for(var g in groups){
  var path=groups[g].path_word;
  var gname=groups[g].name;
  var offset=0,total=1;
  while(offset<total){
    var url='https://api.copy2000.online/api/v3/comic/'+cid+'/group/'+path+'/chapters?limit=100&offset='+offset+'&in_mainland=true';
    var jd=JSON.parse(java.ajax(url));
    var list=jd.results.list;
    total=jd.results.total;
    for(var i=0;i<list.length;i++){
      var n=(gname?gname+' | ':'')+list[i].name;
      out.push({name:n,url:'https://api.copy2000.online/api/v3/comic/'+cid+'/chapter2/'+list[i].uuid+'?in_mainland=true'});
    }
    offset+=100;
  }
}
return out;})()

ruleContent.content:
@js:(function(){
var d=JSON.parse(result).results.chapter;
var contents=d.contents||[];
var words=d.words||[];
var imgs=new Array(contents.length);
for(var i=0;i<contents.length;i++){
  var u=contents[i].url.replace(/([.\/])c\d+x\.[a-zA-Z]+$/,'$1c1500x.webp');
  var idx=(words&&words[i]!=null)?words[i]:i;
  imgs[idx]=u;
}
var out=[];
for(var i=0;i<imgs.length;i++){if(imgs[i])out.push('<img src="'+imgs[i]+'">');}
return out.join('\n');})()
